def max_pool():
    return CONFIG['db']['pool']['max']

def pool_timeout():
    return CONFIG['db']['pool']['timeout']

output:
**Issue:** Callers reach through four levels of nested dict on every access.
**Why:** Typos fail at runtime, there is no IDE navigation, and the config shape cannot be refactored without touching every consumer.
**Fix:**
from dataclasses import dataclass

@dataclass(frozen=True)
class PoolConfig:
    max: int
    timeout: float

@dataclass(frozen=True)
class DbConfig:
    pool: PoolConfig

