class UserService:
    def __init__(self, api_key):
        self.session = requests.Session()
        self.session.headers['Authorization'] = f'Bearer {api_key}'
        self.me = self.session.get('https://api.example.com/me').json()

output:
**Issue:** Constructor performs network I/O.
**Why:** Instantiating the object can hang, raise, or be impossible offline; unit tests cannot even build the object without a mock server.
**Fix:**
class UserService:
    def __init__(self, api_key):
        self.session = requests.Session()
        self.session.headers['Authorization'] = f'Bearer {api_key}'
    @classmethod
    def create(cls, api_key):
        svc = cls(api_key)
        svc.me = svc.session.get('https://api.example.com/me', timeout=10).json()
        return svc

