function onDone(err, result) {
  console.log(result);
}
function onFail(result, err) {
  console.log(err);
}
api.get(url, onDone);
api.del(url, onFail);

output:
**Issue:** Callback signatures are inconsistent across methods.
**Why:** Consumers swap arguments and log `undefined`; the error-first convention exists precisely to avoid this.
**Fix:**
function onDone(err, result) {
  if (err) throw err;
  console.log(result);
}
api.get(url, onDone);
api.del(url, onDone);   // same (err, result) contract everywhere

